from pathlib import Path
svg='<svg xmlns="http://www.w3.org/2000/svg" width="680" height="110" viewBox="0 0 680 110" role="img">\n<title>Shields dynamic json</title><desc>endpoint badge from json</desc>\n<rect width="680" height="110" rx="16" fill="#0f172a"/>\n<text x="20" y="28" fill="#e2e8f0" font-family="monospace" font-size="12">SHIELDS DYNAMIC — endpoint from your API</text>\n<g transform="translate(20,40)">\n  <rect width="260" height="28" rx="6" fill="#1e293b"/><rect x="90" width="170" height="28" rx="6" fill="#38bdf8"/>\n  <text x="10" y="18" fill="#e2e8f0" font-family="monospace" font-size="11">build</text><text x="120" y="18" fill="white" font-family="monospace" font-size="11">passing</text>\n  <text x="285" y="18" fill="#94a3b8" font-family="monospace" font-size="9">https://img.shields.io/endpoint?url=https://your.api/badge.json</text>\n</g>\n</svg>\n'
Path(__file__).resolve().parents[2].joinpath('assets','shields-dynamic.svg').write_text(svg, encoding='utf-8')
